const http = require('http');
const crypto = require('crypto');

if (!process.env.AUTH_KEY || process.env.AUTH_KEY.length < 32) {
  throw new Error('AUTH_KEY environment variable must be set and at least 32 bytes long');
}
const AUTH_KEY = Buffer.from(process.env.AUTH_KEY);
const sessions = new Map();

// Binary message format:
// [1 byte: version] [2 bytes: header_len] [header_len bytes: header] [rest: payload]
// Header format: [32 bytes: HMAC] [4 bytes: timestamp] [remaining: username]

function parseUint16(buf, offset) {
  return (buf[offset] << 8) | buf[offset + 1];
}

function parseUint32(buf, offset) {
  // Parse as unsigned 32-bit integer
  const val = ((buf[offset] << 24) | (buf[offset + 1] << 16) | (buf[offset + 2] << 8) | buf[offset + 3]) >>> 0;
  return val;
}

function extractUsername(headerBuf) {
  // Username starts after HMAC (32 bytes) and timestamp (4 bytes)
  const usernameOffset = 32 + 4;
  const usernameLen = headerBuf.length - usernameOffset;
  if (usernameLen <= 0 || usernameLen > 64) return null;
  return headerBuf.slice(usernameOffset, usernameOffset + usernameLen).toString('utf8');
}

function computeHMAC(data) {
  return crypto.createHmac('sha256', AUTH_KEY).update(data).digest();
}

function verifyMessage(rawBuf) {
  if (!Buffer.isBuffer(rawBuf) || rawBuf.length < 3) return null;

  const version = rawBuf[0];
  if (version !== 1) return null;

  const headerLen = parseUint16(rawBuf, 1);

  // Security check: header must fit within message
  if (headerLen > rawBuf.length - 3) return null;

  // Security check: header must be at least HMAC + timestamp
  if (headerLen < 36) return null;

  // Security check: header length upper bound
  if (headerLen > 128) return null;

  const header = rawBuf.slice(3, 3 + headerLen);
  const payload = rawBuf.slice(3 + headerLen);

  // Limit payload size
  if (payload.length > 4096) return null;

  // Extract HMAC from header
  const receivedHMAC = header.slice(0, 32);

  // Data to verify: everything after HMAC in header + payload
  const signedData = Buffer.concat([header.slice(32), payload]);
  const expectedHMAC = computeHMAC(signedData);

  if (!crypto.timingSafeEqual(receivedHMAC, expectedHMAC)) return null;

  // Extract timestamp and check freshness (unsigned interpretation)
  const timestamp = parseUint32(header, 32);
  const now = Math.floor(Date.now() / 1000);

  // Allow 5 minute window - unsigned comparison prevents wraparound
  if (now < timestamp) return null;
  const timeDiff = now - timestamp;
  if (timeDiff > 300) return null;

  const username = extractUsername(header);
  if (!username) return null;

  // Validate username contains only safe characters
  if (!/^[a-zA-Z0-9._-]+$/.test(username)) return null;

  return { username, payload, timestamp };
}

function handleAuth(rawBuf) {
  const result = verifyMessage(rawBuf);
  if (!result) return { error: 'Authentication failed' };

  const sessionId = crypto.randomBytes(16).toString('hex');
  sessions.set(sessionId, { 
    username: result.username, 
    created: Date.now(),
    payload: result.payload.toString('utf8')
  });
  return { sessionId, username: result.username };
}

function handleQuery(sessionId, query) {
  if (typeof sessionId !== 'string' || sessionId.length !== 32) {
    return { error: 'Invalid session format' };
  }

  const session = sessions.get(sessionId);
  if (!session) return { error: 'Invalid session' };

  // Session expiry: 1 hour
  if (Date.now() - session.created > 3600000) {
    sessions.delete(sessionId);
    return { error: 'Session expired' };
  }

  // Sanitize query for output
  const safeQuery = String(query).slice(0, 200);
  return { data: `Query result for ${session.username}: ${safeQuery}` };
}

const server = http.createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('X-Content-Type-Options', 'nosniff');

  if (req.method === 'POST' && req.url === '/auth') {
    const chunks = [];
    let totalLen = 0;
    req.on('data', chunk => {
      totalLen += chunk.length;
      if (totalLen > 8192) {
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (totalLen > 8192) {
        res.statusCode = 413;
        res.end(JSON.stringify({ error: 'Payload too large' }));
        return;
      }
      const rawBuf = Buffer.concat(chunks);
      const result = handleAuth(rawBuf);
      res.statusCode = result.error ? 401 : 200;
      res.end(JSON.stringify(result));
    });
  } else if (req.method === 'GET' && req.url.startsWith('/query')) {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const sessionId = req.headers['x-session-id'];
    const query = url.searchParams.get('q') || '';
    const result = handleQuery(sessionId, query);
    res.statusCode = result.error ? 403 : 200;
    res.end(JSON.stringify(result));
  } else {
    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);
module.exports = { verifyMessage, handleAuth, handleQuery, parseUint16, parseUint32 };
